8: import { checkRateLimitAndThrowError } from "@calcom/lib/checkRateLimitAndThrowError";
9: import getIP from "@calcom/lib/getIP";
10: import { piiHasher } from "@calcom/lib/server/PiiHasher";
11: import { bookingCancelWithCsrfSchema } from "@calcom/prisma/zod-utils";
12: import { validateCsrfToken } from "@calcom/web/lib/validateCsrfToken";
13: 
14: import { buildLegacyRequest } from "@lib/buildLegacyCtx";
15: 
16: async function handler(req: NextRequest) {
17:   let appDirRequestBody;
18:   try {
19:     appDirRequestBody = await req.json();
20:   } catch {
21:     return NextResponse.json({ success: false, message: "Invalid JSON" }, { status: 400 });
22:   }
23:   const bookingData = bookingCancelWithCsrfSchema.parse(appDirRequestBody);
24: 
25:   // Integer IDs are sequential/guessable — only accept high-entropy UIDs on this route
26:   if (!bookingData.uid) {
27:     return NextResponse.json(
28:       { success: false, message: "uid is required for booking cancellation" },
29:       { status: 400 }
30:     );
31:   }
32: 
33:   const csrfError = await validateCsrfToken(bookingData.csrfToken);
34:   if (csrfError) {
35:     return csrfError;
36:   }
37: 
38:   const session = await getServerSession({ req: buildLegacyRequest(await headers(), await cookies()) });
39: 
40:   // Rate limit: 10 booking cancellations per 60 seconds per user (or IP if not authenticated)
41:   const identifier = session?.user?.id
42:     ? `api:cancel-user:${session.user.id}`
43:     : `api:cancel-ip:${piiHasher.hash(getIP(req))}`;
44:   await checkRateLimitAndThrowError({
45:     rateLimitingType: "core",
46:     identifier,
47:   });
48: 
49:   // Strip integer id to ensure lookup is always by uid
50:   const { id: _id, ...safeBookingData } = bookingData;
51: 
52:   const result = await handleCancelBooking({
53:     bookingData: safeBookingData,
54:     userId: session?.user?.id || -1,
55:   });
56: 
57:   // const bookingCancelService = getBookingCancelService();
58:   // const result = await bookingCancelService.cancelBooking({
59:   //   bookingData: bookingData,
60:   //   bookingMeta: {
61:   //     userId: session?.user?.id || -1,
62:   //   },
63:   // });
64: 
65:   const statusCode = result.success ? 200 : 400;
66: 
67:   return NextResponse.json(result, { status: statusCode });
68: }
