51: export const useSchedule = ({
52:   month,
53:   timezone,
54:   username,
55:   eventSlug,
56:   eventId,
57:   selectedDate,
58:   duration,
59:   dayCount,
60:   rescheduleUid,
61:   isTeamEvent,
62:   orgSlug,
63:   teamMemberEmail,
64:   useApiV2 = false,
65:   enabled: enabledProp = true,
66:   bookerLayout,
67: }: UseScheduleWithCacheArgs) => {
68:   const bookerState = useBookerStore((state) => state.state);
69: 
70:   const [startTime, endTime] = useTimesForSchedule({
71:     month,
72:     dayCount,
73:     selectedDate,
74:     bookerLayout,
75:   });
76:   const searchParams = useSearchParams();
77:   const routedTeamMemberIds = searchParams
78:     ? getRoutedTeamMemberIdsFromSearchParams(new URLSearchParams(searchParams.toString()))
79:     : null;
80:   const skipContactOwner = searchParams ? searchParams.get("cal.skipContactOwner") === "true" : false;
81:   const utils = trpc.useUtils();
82:   const queuedFormResponseId = searchParams?.get("cal.queuedFormResponseId");
83:   const email = searchParams?.get("email");
84:   // We allow skipping the schedule fetch as a requirement for prerendering in iframe through embed as when the pre-rendered iframe is connected, then we would fetch the availability, which would be upto-date
85:   // Also, a reuse through Headless Router could completely change the availability as different team members are selected and thus it is unnecessary to fetch the schedule
86:   const skipGetSchedule = searchParams?.get("cal.skipSlotsFetch") === "true";
87:   const embedConnectVersion = searchParams?.get("cal.embed.connectVersion") || "0";
88:   const input = {
89:     isTeamEvent,
90:     usernameList: getUsernameList(username ?? ""),
91:     // Prioritize slug over id, since slug is the first value we get available.
92:     // If we have a slug, we don't need to fetch the id.
93:     // TODO: are queries using eventTypeId faster? Even tho we lost time fetching the id with the slug.
94:     ...(eventSlug ? { eventTypeSlug: eventSlug } : { eventTypeId: eventId ?? 0 }),
95:     // @TODO: Old code fetched 2 days ago if we were fetching the current month.
96:     // Do we want / need to keep that behavior?
97:     startTime,
98:     // if `prefetchNextMonth` is true, two months are fetched at once.
99:     endTime,
100:     // We use a placeholder value that is there to keep TS happy, but still invalid to tell us that it shouldn't actually be passed in request(and wouldn't because enabled is false if timezone is nullish)
101:     // TODO: Better approach here is to use `skipToken` from react-query which requires an upgrade of react-query
102:     timeZone: timezone ?? "PLACEHOLDER_TIMEZONE",
103:     duration: duration ? `${duration}` : undefined,
104:     rescheduleUid,
105:     orgSlug,
106:     teamMemberEmail,
107:     routedTeamMemberIds,
108:     skipContactOwner,
109:     ...(queuedFormResponseId ? { queuedFormResponseId } : {}),
110:     email,
111:     // Ensures that connectVersion causes a refresh of the data
112:     ...(embedConnectVersion ? { embedConnectVersion } : {}),
113:     _isDryRun: searchParams ? isBookingDryRun(searchParams) : false,
114:   };
115: 
116:   const options = {
117:     trpc: {
118:       context: {
119:         skipBatch: true,
120:       },
121:     },
122:     // It allows people who might not have the tab in focus earlier, to get latest available slots
123:     // It might not work correctly in iframes, so we have refetchInterval to take care of that.
124:     // But where it works, it should give user latest availability even if they come back to tab before refetchInterval.
125:     refetchOnWindowFocus: true,
126:     // It allows long sitting users to get latest available slots
127:     refetchInterval: PUBLIC_QUERY_AVAILABLE_SLOTS_INTERVAL_SECONDS * 1000,
128:     enabled:
129:       !skipGetSchedule &&
130:       Boolean(username) &&
131:       Boolean(month) &&
132:       Boolean(timezone) &&
133:       // Should only wait for one or the other, not both.
134:       (Boolean(eventSlug) || Boolean(eventId) || eventId === 0) &&
135:       enabledProp,
136:   };
137: 
138:   const isCallingApiV2Slots = useApiV2 && Boolean(isTeamEvent) && options.enabled;
139: 
140:   // API V2 query for team events
141:   const teamScheduleV2 = useApiV2AvailableSlots({
142:     ...input,
143:     enabled: isCallingApiV2Slots,
144:     duration: input.duration ? Number(input.duration) : undefined,
145:     routedTeamMemberIds: input.routedTeamMemberIds ?? undefined,
146:     teamMemberEmail: input.teamMemberEmail ?? undefined,
147:     eventTypeId: eventId ?? undefined,
148:   });
149: 
150:   const schedule = trpc.viewer.slots.getSchedule.useQuery(input, {
151:     ...options,
152:     // Only enable if we're not using API V2
153:     enabled: options.enabled && !isCallingApiV2Slots,
154:   });
155: 
156:   if (isCallingApiV2Slots && !teamScheduleV2.failureReason) {
157:     updateEmbedBookerState({
158:       bookerState,
159:       slotsQuery: teamScheduleV2,
160:     });
161: 
162:     if (teamScheduleV2.isSuccess && eventId && eventSlug) {
163:       sdkActionManager?.fire("availabilityLoaded", getAvailabilityLoadedEventPayload({ eventId, eventSlug }));
164:     }
165: 
166:     return {
167:       ...teamScheduleV2,
168:       /**
169:        * Invalidates the request and resends it regardless of any other configuration including staleTime
170:        */
171:       invalidate: () => {
172:         return teamScheduleV2.refetch();
173:       },
174:     };
175:   }
176: 
177:   updateEmbedBookerState({
178:     bookerState,
179:     slotsQuery: schedule,
180:   });
181: 
182:   if (schedule.isSuccess && eventId && eventSlug) {
183:     sdkActionManager?.fire("availabilityLoaded", getAvailabilityLoadedEventPayload({ eventId, eventSlug }));
184:   }
185: 
186:   return {
187:     ...schedule,
188:     /**
189:      * Invalidates the request and resends it regardless of any other configuration including staleTime
190:      */
191:     invalidate: () => {
192:       return utils.viewer.slots.getSchedule.invalidate(input);
193:     },
194:   };
195: };

