10: export function getNewSearchParams(args: {
11:   query: Record<string, string | null | undefined | boolean>;
12:   searchParams?: URLSearchParams;
13:   filterInternalParams?: boolean;
14: }) {
15:   const { query, searchParams, filterInternalParams = false } = args;
16:   const newSearchParams = new URLSearchParams();
17: 
18:   // Embed-specific params
19:   const embedParams = new Set(["embed", "layout", "embedType", "ui.color-scheme"]);
20: 
21:   // Webapp-specific params
22:   const webappParams = new Set(["overlayCalendar"]);
23: 
24:   // Add non-excluded params from searchParams if provided
25:   if (searchParams) {
26:     searchParams.forEach((value, key) => {
27:       if (shouldExcludeParam(key)) {
28:         return;
29:       }
30:       newSearchParams.append(key, value);
31:     });
32:   }
33: 
34:   // Add params from query, filtering excluded params
35:   Object.entries(query).forEach(([key, value]) => {
36:     if (value === null || value === undefined) {
37:       return;
38:     }
39: 
40:     if (shouldExcludeParam(key)) {
41:       return;
42:     }
43: 
44:     newSearchParams.append(key, String(value));
45:   });
46: 
47:   function shouldExcludeParam(key: string) {
48:     if (filterInternalParams) {
49:       return embedParams.has(key) || webappParams.has(key);
50:     }
51:     return false;
52:   }
53: 
54:   return newSearchParams;
55: }
