57: type SuccessRedirectBookingType = Pick<
58:   BookingResponse,
59:   "uid" | "title" | "description" | "startTime" | "endTime" | "location" | "attendees" | "user" | "responses"
60: >;
61: 
62: type BookingResponseKey = keyof SuccessRedirectBookingType;
63: 
64: type ResultType = {
65:   [key in BookingResponseKey]?: SuccessRedirectBookingType[key];
66: } & {
67:   hostName?: string[];
68:   attendeeName?: string | null;
69:   hostStartTime?: string | null;
70:   attendeeStartTime?: string | null;
71:   guestEmails?: string[] | null;
72:   phone?: string | null;
73:   attendeeFirstName?: string | null;
74:   attendeeLastName?: string | null;
75: };
76: 
77: export const getBookingRedirectExtraParams = (booking: SuccessRedirectBookingType) => {
78:   const redirectQueryParamKeys: BookingResponseKey[] = [
79:     "title",
80:     "description",
81:     "startTime",
82:     "endTime",
83:     "location",
84:     "attendees",
85:     "user",
86:     "responses",
87:   ];
88: 
89:   // Helper function to extract response details (e.g., phone, attendee's first and last name)
90:   function extractResponseDetails(booking: SuccessRedirectBookingType, obj: ResultType): ResultType {
91:     const result: ResultType = { ...obj };
92:     const phone = getSafe<string>(booking.responses, ["phone"]);
93:     const firstName = getSafe<string>(booking.responses, ["name", "firstName"]);
94:     const lastName = getSafe<string>(booking.responses, ["name", "lastName"]);
95:     const name = getSafe<string>(booking.responses, ["name"]);
96: 
97:     if (phone) result.phone = phone;
98:     if (firstName) result.attendeeFirstName = firstName;
99:     if (lastName) result.attendeeLastName = lastName;
100:     else if (name && typeof name === "string") result.attendeeName = name; // Fallback if `name` is a string instead of an object
101: 
102:     return result;
103:   }
104: 
105:   // Helper function to extract user details (e.g., host name and time zone)
106:   function extractUserDetails(booking: SuccessRedirectBookingType, obj: ResultType): ResultType {
107:     if (booking.user?.name) {
108:       const hostStartTime = dayjs(booking.startTime).tz(booking.user.timeZone).format();
109:       return {
110:         ...obj,
111:         hostName: [...(obj.hostName || []), booking.user.name],
112:         hostStartTime,
113:       };
114:     }
115:     return obj;
116:   }
117: 
118:   // Helper function to extract attendee and guest details
119:   function extractAttendeesAndGuests(booking: SuccessRedirectBookingType, obj: ResultType): ResultType {
120:     if (!Array.isArray(booking.attendees) || booking.attendees.length === 0) return obj;
121: 
122:     const attendeeName = booking.attendees[0]?.name || null;
123:     const attendeeTimeZone = booking.attendees[0]?.timeZone || "UTC";
124:     const attendeeStartTime = dayjs(booking.startTime).tz(attendeeTimeZone).format();
125: 
126:     const { hostNames, guestEmails } = booking.attendees.slice(1).reduce(
127:       (acc, attendee) => {
128:         if (attendee.name) {
129:           acc.hostNames.push(attendee.name);
130:         } else if (attendee.email) {
131:           acc.guestEmails.push(attendee.email);
132:         }
133:         return acc;
134:       },
135:       { hostNames: [], guestEmails: [] } as { hostNames: string[]; guestEmails: string[] }
136:     );
137: 
138:     return {
139:       ...obj,
140:       attendeeName,
141:       attendeeStartTime,
142:       hostName: [...(obj.hostName || []), ...hostNames],
143:       guestEmails: guestEmails.length > 0 ? guestEmails : undefined,
144:     };
145:   }
146: 
147:   const bookingParams = (Object.keys(booking) as BookingResponseKey[])
148:     .filter((key) => redirectQueryParamKeys.includes(key))
149:     .reduce<ResultType>(
150:       (obj, key) => {
151:         if (key === "responses") return extractResponseDetails(booking, obj);
152:         if (key === "user") return extractUserDetails(booking, obj);
153:         if (key === "attendees") return extractAttendeesAndGuests(booking, obj);
154:         return { ...obj, [key]: booking[key] };
155:       },
156:       { uid: booking.uid }
157:     );
158: 
159:   const queryCompatibleParams: Record<string, string | boolean | null | undefined> = {
160:     ...Object.fromEntries(
161:       Object.entries(bookingParams).map(([key, value]) => {
162:         if (Array.isArray(value)) {
163:           return [key, value.join(", ")];
164:         }
165:         if (typeof value === "object" && value !== null) {
166:           // Skip complex objects (user, attendees) as we are extracting only needed fields
167:           return [key, undefined];
168:         }
169:         return [key, value];
170:       })
171:     ),
172:     hostName: bookingParams.hostName?.join(", "),
173:     attendeeName: bookingParams.attendeeName || undefined,
174:     hostStartTime: bookingParams.hostStartTime || undefined,
175:     attendeeStartTime: bookingParams.attendeeStartTime || undefined,
176:   };
177: 
178:   return queryCompatibleParams;
179: };
