121: 
122:   if (originalRescheduledBooking?.paid && originalRescheduledBooking?.payment) {
123:     const bookingPayment = originalRescheduledBooking.payment.find((payment) => payment.success);
124:     if (bookingPayment) {
125:       createBookingObj.data.payment = { connect: { id: bookingPayment.id } };
