139:   return prisma.$transaction(async (tx) => {
140:     if (originalBookingUpdateDataForCancellation) {
141:       await tx.booking.update(originalBookingUpdateDataForCancellation);
142:     }
143: 
144:     const booking = await tx.booking.create(createBookingObj);
145: 
146:     return { ...booking, userUuid: booking.user?.uuid ?? null };
147:   });
148: }
